import{_ as a,o as t,c as i,ag as r}from"./chunks/framework.BZohXCq9.js";const m=JSON.parse('{"title":"CmaFree=0 不等于内存耗尽：一次 RK3588 DMA-BUF 排障复盘","description":"从 CmaFree=0 的误判出发，复盘如何结合 kernel config、DMA-BUF owner、分配失败计数和重启行为判断真实 CMA 压力","frontmatter":{"title":"CmaFree=0 不等于内存耗尽：一次 RK3588 DMA-BUF 排障复盘","description":"从 CmaFree=0 的误判出发，复盘如何结合 kernel config、DMA-BUF owner、分配失败计数和重启行为判断真实 CMA 压力","tags":["RK3588","CMA","DMA-BUF","Linux","问题复盘"],"date":"2026/07/20"},"headers":[],"relativePath":"linux/rk3588-cma-dmabuf-memory-debug.md","filePath":"linux/rk3588-cma-dmabuf-memory-debug.md","lastUpdated":1784519165000}'),o={name:"linux/rk3588-cma-dmabuf-memory-debug.md"};function l(d,e,n,c,s,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="cmafree-0-不等于内存耗尽-一次-rk3588-dma-buf-排障复盘" tabindex="-1">CmaFree=0 不等于内存耗尽：一次 RK3588 DMA-BUF 排障复盘 <a class="header-anchor" href="#cmafree-0-不等于内存耗尽-一次-rk3588-dma-buf-排障复盘" aria-label="Permalink to &quot;CmaFree=0 不等于内存耗尽：一次 RK3588 DMA-BUF 排障复盘&quot;">​</a></h1><p>看到 <code>/proc/meminfo</code> 里的 <code>CmaFree: 0 kB</code>，最自然的结论是“CMA 已经耗尽”。这次排障最有价值的地方，就是证明了这个结论在特定 Rockchip kernel 配置下完全错误。</p><p>如果当时直接扩大 CMA，只会继续挤占普通 RAM，却没有解决任何真实问题。</p><h2 id="现场-数字看起来非常危险" tabindex="-1">现场：数字看起来非常危险 <a class="header-anchor" href="#现场-数字看起来非常危险" aria-label="Permalink to &quot;现场：数字看起来非常危险&quot;">​</a></h2><p>板端运行着相机采集、ISP、鱼眼处理、视觉算法和 NPU 推理。现场读数大致是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CmaTotal: 1048576 kB</span></span>\n<span class="line"><span>CmaFree:        0 kB</span></span>\n<span class="line"><span>MemAvailable:   5.6 ~ 6.7 GiB</span></span></code></pre></div><p>一边是 1 GiB CMA 全部显示“不可用”，另一边是普通内存仍然充足。单看这三个数字，无法判断到底是 CMA 真耗尽、统计口径异常，还是内核采用了不同的页管理语义。</p><h2 id="第一次误判-把-cmafree-当成真实余量" tabindex="-1">第一次误判：把 <code>CmaFree</code> 当成真实余量 <a class="header-anchor" href="#第一次误判-把-cmafree-当成真实余量" aria-label="Permalink to &quot;第一次误判：把 `CmaFree` 当成真实余量&quot;">​</a></h2><p>最初的排查方向很容易落到“谁吃光了 1 GiB”。但通过 DMA-BUF 统计，能看到的主要占用只有约 <code>237~246 MiB</code>：</p><table tabindex="0"><thead><tr><th>Owner 类型</th><th style="text-align:right;">可见 DMA-BUF 占用</th></tr></thead><tbody><tr><td>NPU/视觉算法进程</td><td style="text-align:right;">约 152 MiB</td></tr><tr><td>相机流水线</td><td style="text-align:right;">约 50~58 MiB</td></tr><tr><td>ISP/3A 服务</td><td style="text-align:right;">约 33 MiB</td></tr><tr><td>其他图形进程</td><td style="text-align:right;">少量</td></tr></tbody></table><p>可见占用和 1 GiB 之间存在巨大差距。如果这时继续盯着 <code>CmaFree</code>，分析就会陷入“还有几百 MiB 到底去哪了”的错误问题。</p><h2 id="证据怎样收敛" tabindex="-1">证据怎样收敛 <a class="header-anchor" href="#证据怎样收敛" aria-label="Permalink to &quot;证据怎样收敛&quot;">​</a></h2><p>这类内存问题不能依赖一个指标。我最终把证据拆成四层：</p><h3 id="_1-先看普通内存是否真的紧张" tabindex="-1">1. 先看普通内存是否真的紧张 <a class="header-anchor" href="#_1-先看普通内存是否真的紧张" aria-label="Permalink to &quot;1. 先看普通内存是否真的紧张&quot;">​</a></h3><p><code>MemAvailable</code> 仍有数 GiB，说明系统并没有普通意义上的内存耗尽。它不能证明 CMA 健康，但可以排除“全系统已经濒临 OOM”的叙述。</p><h3 id="_2-再看-dma-buf-owner" tabindex="-1">2. 再看 DMA-BUF owner <a class="header-anchor" href="#_2-再看-dma-buf-owner" aria-label="Permalink to &quot;2. 再看 DMA-BUF owner&quot;">​</a></h3><p><code>/sys/kernel/debug/dma_buf/bufinfo</code> 能回答谁持有可见 DMA-BUF，以及每个 owner 大致占了多少。它比只看进程 RSS 更接近相机、RGA、DRM 和 NPU 的真实共享内存路径。</p><p>不过，bufinfo 也不是全知视角。驱动内部池、不可见的连续内存和短时峰值仍可能不在当前快照里，所以不能拿“可见总量”直接等同于完整 CMA 使用量。</p><h3 id="_3-检查分配成功与失败" tabindex="-1">3. 检查分配成功与失败 <a class="header-anchor" href="#_3-检查分配成功与失败" aria-label="Permalink to &quot;3. 检查分配成功与失败&quot;">​</a></h3><p>现场 <code>cma_alloc_fail</code> 持续为 0，短时采样期间 DMA-BUF 总量也没有不断增长。这个证据比 <code>CmaFree</code> 更关键：至少在当前负载下，没有看到连续内存分配失败。</p><h3 id="_4-最后查-kernel-config" tabindex="-1">4. 最后查 kernel config <a class="header-anchor" href="#_4-最后查-kernel-config" aria-label="Permalink to &quot;4. 最后查 kernel config&quot;">​</a></h3><p>决定性证据是内核启用了：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_CMA_INACTIVE=y</span></span></code></pre></div><p>在这套内核语义里，CMA 页不会按通常方式激活到普通页分配器，因此 <code>CmaFree</code> / <code>nr_free_cma</code> 不能直接代表仍可用于 CMA 分配的 headroom。<code>0 kB</code> 是统计语义的结果，不等于所有连续内存已经被业务占用。</p><h2 id="根因-用错了指标-不是内存突然消失" tabindex="-1">根因：用错了指标，不是内存突然消失 <a class="header-anchor" href="#根因-用错了指标-不是内存突然消失" aria-label="Permalink to &quot;根因：用错了指标，不是内存突然消失&quot;">​</a></h2><p>这次问题的根因不是某个进程泄漏了 1 GiB，而是诊断方法默认套用了另一种 kernel 配置下的指标解释。</p><p>真正应该关注的是：</p><ul><li>kernel 是否启用特殊 CMA 模式；</li><li><code>cma_alloc_success</code> / <code>cma_alloc_fail</code> 是否恶化；</li><li>DMA-BUF owner 和总量是否持续增长；</li><li>服务重启时是否出现双池重叠和分配失败；</li><li>长时间运行是否存在稳定的内存斜率。</li></ul><h2 id="_384-mib-还是-512-mib" tabindex="-1">384 MiB 还是 512 MiB <a class="header-anchor" href="#_384-mib-还是-512-mib" aria-label="Permalink to &quot;384 MiB 还是 512 MiB&quot;">​</a></h2><p>现场可见 DMA-BUF 约 238 MiB。若只做静态减法，384 MiB 似乎还剩约 146 MiB；但生产系统还要覆盖驱动内部占用、服务重启时新旧 buffer pool 重叠、RGA/MPP/ISP 峰值和诊断流临时开启。</p><p>因此这次最终选择是 <strong>512 MiB</strong>，而不是 384 MiB。</p><p>这个结论不是说 384 MiB 一定运行不了，而是它给重启和峰值留下的工程余量偏小。1 GiB 同样没有必要，因为在 <code>CMA_INACTIVE</code> 模式下，过大的 CMA 会真实挤占普通 RAM。</p><h2 id="哪些证据还不够" tabindex="-1">哪些证据还不够 <a class="header-anchor" href="#哪些证据还不够" aria-label="Permalink to &quot;哪些证据还不够&quot;">​</a></h2><p>短时间内 <code>cma_alloc_fail=0</code>，不能证明系统永远不会泄漏。两分钟采样也不能代替一小时以上的 steady-state、循环重启和高峰负载测试。</p><p>最终验收至少应包含：</p><ol><li>生产负载长时间运行；</li><li>相机、算法和编码服务循环重启；</li><li>同时观察 DMA-BUF owner、分配失败和普通内存；</li><li>明确区分生产态与开启额外诊断流的状态；</li><li>记录峰值而不是只看最后一帧。</li></ol><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>内核指标没有上下文就没有结论。<code>CmaFree=0</code> 只是一个现象，只有把 kernel config、DMA-BUF owner、分配失败和重启行为连起来，才能判断 CMA 是否真的不足。</p><p>这次排障避免了一个典型的“看到危险数字就扩容”的错误修复，也把容量选择从感觉变成了可以复测的工程决策。</p><p>参考：<a href="https://docs.kernel.org/driver-api/dma-buf.html" target="_blank" rel="noreferrer">Linux Kernel DMA-BUF 文档</a>。</p>',40)])])}const u=a(o,[["render",l]]);export{m as __pageData,u as default};
